import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../state/app_state.dart';
class ProfileScreen extends ConsumerWidget{const ProfileScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final app=ref.watch(appStateProvider);final e=Map<String,dynamic>.from((app.me['employee'] as Map?)??const{});return ListView(padding:const EdgeInsets.all(16),children:[Text('Profile',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),Card(child:Column(children:[ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text('${e['full_name']??'-'}'),subtitle:Text('${e['employee_code']??''} · ${e['designation_code']??''}')),const Divider(height:1),ListTile(leading:const Icon(Icons.phone_outlined),title:Text('${e['mobile']??'-'}')),ListTile(leading:const Icon(Icons.email_outlined),title:Text('${e['email']??'-'}')),ListTile(leading:const Icon(Icons.account_tree_outlined),title:Text('Reporting Employee: ${e['reporting_employee_id']??'-'}'))])),const SizedBox(height:16),OutlinedButton.icon(onPressed:()=>ref.read(appStateProvider.notifier).logout(),icon:const Icon(Icons.logout),label:const Text('Logout'))]);}}
